from collections import deque

def max_sliding_window(nums, k):
    dq = deque()  # indices, values non-increasing
    ans = []
    for i, x in enumerate(nums):
        if dq and dq[0] <= i - k:
            dq.popleft()               # expired index
        while dq and nums[dq[-1]] <= x:
            dq.pop()                   # dominated candidates
        dq.append(i)
        if i >= k - 1:
            ans.append(nums[dq[0]])
    return ans

